SELECT "t12"."order_number", "t12"."line_no", "t12"."item", "t12"."quantity", "t12"."on_hand", "t12"."outage", "t12"."short", 'hold_sales' AS "route", 'shortfall' AS "context"
FROM (SELECT "order_number", "line_no", "item", "quantity", "on_hand", "outage", "quantity" - "on_hand" AS "short"
        FROM (SELECT "t8"."order_number", "t8"."customer", "t8"."channel", "t8"."fulfilling_warehouse", "t8"."value", "t8"."placed_date", "t8"."state", "t8"."line_no", "t8"."item", "t8"."quantity", "t8"."unit_price", "t8"."ext_sales_price", "t8"."warehouse", "t8"."sold_date", "t8"."customer0", "t8"."channel0", "t8"."as_of_date", "t8"."quantity_on_hand", "t8"."_ttrp_g_n9_0", "t8"."_ttrp_g_n9_1", "t9"."warehouse" AS "warehouse0", "t9"."from_date", "t9"."to_date", "t9"."reason", COALESCE("t8"."quantity_on_hand", 0) AS "on_hand", "t9"."warehouse" IS NOT NULL AS "outage"
                FROM (SELECT "t2"."order_number", "t2"."customer", "t2"."channel", "t2"."fulfilling_warehouse", "t2"."value", "t2"."placed_date", "t2"."state", "t2"."line_no", "t2"."item", "t2"."quantity", "t2"."unit_price", "t2"."ext_sales_price", "t2"."warehouse", "t2"."sold_date", "t2"."customer0", "t2"."channel0", "t2"."as_of_date", "t2"."quantity_on_hand", "t2"."_ttrp_g_n9_0", "t2"."_ttrp_g_n9_1"
                        FROM (SELECT "t1"."order_number", "t1"."customer", "t1"."channel", "t1"."fulfilling_warehouse", "t1"."value", "t1"."placed_date", "t1"."state", "t1"."line_no", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."ext_sales_price", "t1"."warehouse", "t1"."sold_date", "t1"."customer0", "t1"."channel0", "inventory"."as_of_date", "inventory"."quantity_on_hand", CASE WHEN "t1"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t1"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t1"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t1"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                FROM "order"
                                                WHERE "state" IN ('held', 'placed')) AS "t0"
                                            INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                                    LEFT JOIN "inventory" ON "t1"."item" = "inventory"."item" AND "t1"."warehouse" = "inventory"."warehouse") AS "t2"
                            INNER JOIN (SELECT CASE WHEN "t5"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t5"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory0"."as_of_date") AS "_ttrp_latest_n9"
                                FROM (SELECT "t4"."order_number", "t4"."customer", "t4"."channel", "t4"."fulfilling_warehouse", "t4"."value", "t4"."placed_date", "t4"."state", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."quantity", "sales_line0"."unit_price", "sales_line0"."ext_sales_price", "sales_line0"."warehouse", "sales_line0"."sold_date", "sales_line0"."customer" AS "customer0", "sales_line0"."channel" AS "channel0"
                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                FROM "order"
                                                WHERE "state" IN ('held', 'placed')) AS "t4"
                                            INNER JOIN "sales_line" AS "sales_line0" ON "t4"."order_number" = "sales_line0"."order_number") AS "t5"
                                    LEFT JOIN "inventory" AS "inventory0" ON "t5"."item" = "inventory0"."item" AND "t5"."warehouse" = "inventory0"."warehouse"
                                GROUP BY CASE WHEN "t5"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."order_number" AS VARCHAR) END, CASE WHEN "t5"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."line_no" AS VARCHAR) END) AS "t7" ON "t2"."_ttrp_g_n9_0" = "t7"."_ttrp_g_n9_0" AND "t2"."_ttrp_g_n9_1" = "t7"."_ttrp_g_n9_1" AND "t2"."as_of_date" = "t7"."_ttrp_latest_n9") AS "t8"
                    LEFT JOIN (SELECT *
                        FROM "warehouse_outage"
                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t9" ON "t8"."warehouse" = "t9"."warehouse") AS "t10"
        WHERE "t10"."outage" OR "t10"."on_hand" < "t10"."quantity") AS "t12"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t42"."order_number", "t42"."customer", "t42"."channel", "t42"."fulfilling_warehouse", "t42"."value", "t42"."placed_date", "t42"."state", COALESCE("t42"."n_short", 0) AS "n_short", COALESCE("t42"."n_price", 0) AS "n_price", COALESCE("t48"."n_due", 0) AS "n_due"
                FROM (SELECT "t30"."order_number", "t30"."customer", "t30"."channel", "t30"."fulfilling_warehouse", "t30"."value", "t30"."placed_date", "t30"."state", "t30"."n_short", "t41"."n_price"
                        FROM (SELECT "t14"."order_number", "t14"."customer", "t14"."channel", "t14"."fulfilling_warehouse", "t14"."value", "t14"."placed_date", "t14"."state", "t29"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t14"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t24"."order_number", "t24"."customer", "t24"."channel", "t24"."fulfilling_warehouse", "t24"."value", "t24"."placed_date", "t24"."state", "t24"."line_no", "t24"."item", "t24"."quantity", "t24"."unit_price", "t24"."ext_sales_price", "t24"."warehouse", "t24"."sold_date", "t24"."customer0", "t24"."channel0", "t24"."as_of_date", "t24"."quantity_on_hand", "t24"."_ttrp_g_n9_0", "t24"."_ttrp_g_n9_1", "t25"."warehouse" AS "warehouse0", "t25"."from_date", "t25"."to_date", "t25"."reason", COALESCE("t24"."quantity_on_hand", 0) AS "on_hand", "t25"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t18"."order_number", "t18"."customer", "t18"."channel", "t18"."fulfilling_warehouse", "t18"."value", "t18"."placed_date", "t18"."state", "t18"."line_no", "t18"."item", "t18"."quantity", "t18"."unit_price", "t18"."ext_sales_price", "t18"."warehouse", "t18"."sold_date", "t18"."customer0", "t18"."channel0", "t18"."as_of_date", "t18"."quantity_on_hand", "t18"."_ttrp_g_n9_0", "t18"."_ttrp_g_n9_1"
                                                        FROM (SELECT "t17"."order_number", "t17"."customer", "t17"."channel", "t17"."fulfilling_warehouse", "t17"."value", "t17"."placed_date", "t17"."state", "t17"."line_no", "t17"."item", "t17"."quantity", "t17"."unit_price", "t17"."ext_sales_price", "t17"."warehouse", "t17"."sold_date", "t17"."customer0", "t17"."channel0", "inventory1"."as_of_date", "inventory1"."quantity_on_hand", CASE WHEN "t17"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t17"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                                                FROM (SELECT "t16"."order_number", "t16"."customer", "t16"."channel", "t16"."fulfilling_warehouse", "t16"."value", "t16"."placed_date", "t16"."state", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."quantity", "sales_line1"."unit_price", "sales_line1"."ext_sales_price", "sales_line1"."warehouse", "sales_line1"."sold_date", "sales_line1"."customer" AS "customer0", "sales_line1"."channel" AS "channel0"
                                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                FROM "order"
                                                                                WHERE "state" IN ('held', 'placed')) AS "t16"
                                                                            INNER JOIN "sales_line" AS "sales_line1" ON "t16"."order_number" = "sales_line1"."order_number") AS "t17"
                                                                    LEFT JOIN "inventory" AS "inventory1" ON "t17"."item" = "inventory1"."item" AND "t17"."warehouse" = "inventory1"."warehouse") AS "t18"
                                                            INNER JOIN (SELECT CASE WHEN "t21"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t21"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t21"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t21"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory2"."as_of_date") AS "_ttrp_latest_n9"
                                                                FROM (SELECT "t20"."order_number", "t20"."customer", "t20"."channel", "t20"."fulfilling_warehouse", "t20"."value", "t20"."placed_date", "t20"."state", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."quantity", "sales_line2"."unit_price", "sales_line2"."ext_sales_price", "sales_line2"."warehouse", "sales_line2"."sold_date", "sales_line2"."customer" AS "customer0", "sales_line2"."channel" AS "channel0"
                                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                FROM "order"
                                                                                WHERE "state" IN ('held', 'placed')) AS "t20"
                                                                            INNER JOIN "sales_line" AS "sales_line2" ON "t20"."order_number" = "sales_line2"."order_number") AS "t21"
                                                                    LEFT JOIN "inventory" AS "inventory2" ON "t21"."item" = "inventory2"."item" AND "t21"."warehouse" = "inventory2"."warehouse"
                                                                GROUP BY CASE WHEN "t21"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t21"."order_number" AS VARCHAR) END, CASE WHEN "t21"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t21"."line_no" AS VARCHAR) END) AS "t23" ON "t18"."_ttrp_g_n9_0" = "t23"."_ttrp_g_n9_0" AND "t18"."_ttrp_g_n9_1" = "t23"."_ttrp_g_n9_1" AND "t18"."as_of_date" = "t23"."_ttrp_latest_n9") AS "t24"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t25" ON "t24"."warehouse" = "t25"."warehouse") AS "t26"
                                        WHERE "t26"."outage" OR "t26"."on_hand" < "t26"."quantity"
                                        GROUP BY "order_number") AS "t29" ON "t14"."order_number" = "t29"."order_number") AS "t30"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t33"."order_number", "t33"."line_no", "t33"."item", "t33"."unit_price", "t33"."customer", "t33"."channel", "t33"."placed_date", "t37"."order_number" AS "order_number0", "t37"."line_no" AS "line_no0", "t37"."price"
                                        FROM (SELECT "sales_line3"."order_number", "sales_line3"."line_no", "sales_line3"."item", "sales_line3"."unit_price", "t32"."customer", "t32"."channel", "t32"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t32"
                                                    INNER JOIN "sales_line" AS "sales_line3" ON "t32"."order_number" = "sales_line3"."order_number") AS "t33"
                                            INNER JOIN (SELECT "t36"."order_number", "t36"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                                FROM (SELECT "sales_line4"."order_number", "sales_line4"."line_no", "sales_line4"."item", "sales_line4"."unit_price", "t35"."customer", "t35"."channel", "t35"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t35"
                                                            INNER JOIN "sales_line" AS "sales_line4" ON "t35"."order_number" = "sales_line4"."order_number") AS "t36"
                                                    LEFT JOIN "customer_price" ON "t36"."item" = "customer_price"."item" AND "t36"."customer" = "customer_price"."customer" AND "t36"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t36"."placed_date" <= "customer_price"."valid_to")
                                                    LEFT JOIN "price_list" ON "t36"."item" = "price_list"."item" AND "t36"."channel" = "price_list"."channel" AND "t36"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t36"."placed_date" <= "price_list"."valid_to")) AS "t37" ON "t33"."order_number" = "t37"."order_number" AND "t33"."line_no" = "t37"."line_no") AS "t38"
                                WHERE "t38"."price" IS NULL OR ABS("t38"."unit_price" - "t38"."price") > :tolerance
                                GROUP BY "order_number0") AS "t41" ON "t30"."order_number" = "t41"."order_number") AS "t42"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t44"."order_number", "t44"."customer", "t44"."channel", "t44"."fulfilling_warehouse", "t44"."value", "t44"."placed_date", "t44"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t44"
                                    INNER JOIN "invoice" ON "t44"."customer" = "invoice"."customer") AS "t45"
                        WHERE "t45"."status" = 'open' AND "t45"."due" < :as_of
                        GROUP BY "order_number") AS "t48" ON "t42"."order_number" = "t48"."order_number") AS "t49"
        WHERE "t49"."n_short" > 0 OR "t49"."n_price" > 0
        GROUP BY "order_number") AS "t52" ON "t12"."order_number" = "t52"."order_number"
